contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint cBefore = address(c).balance;
        uint testBefore = address(this).balance;
        // inert withdrawal attempt with no prior deposit
        c.withdrawAll();
        assert(address(c).balance == cBefore);
        assert(address(this).balance == testBefore);
        // now deposit: contract must hold exactly amount, no leftover effects
        c.deposit{value: amount}();
        assert(address(c).balance == amount);
        assert(address(this).balance == testBefore - amount);
    }
    receive() external payable {}
}

